class Solution {
public:
    bool hasOneConsecutivePair(int n) {
        string s = bitset<20>(n).to_string();
        int cnt = 0;
        for (int i = 0; i < 19; i++)
            if (s[i] == '1' && s[i + 1] == '1') cnt++;
        return cnt == 1;
    }
};

c.java:
class Solution {
    public boolean hasOneConsecutivePair(int n) {
        String s = Integer.toBinaryString(n);
        int cnt = 0;
        for (int i = 0; i < s.length() - 1; i++) {
            if (s.charAt(i) == '1' && s.charAt(i + 1) == '1') cnt++;
        }
        return cnt == 1;
    }
}

